    #[test]
    fn automation_bstr_preserves_units_and_vba_scalar_formatting() {
        use super::{coerce_automation_scalar, AutomationScalarType, Value};
        let cast = |value| coerce_automation_scalar(&value, AutomationScalarType::Bstr).unwrap();
        assert_eq!(cast(Value::Boolean(true)), Value::String("True".into()));
        assert_eq!(cast(Value::Single(1e30)), Value::String("1E+30".into()));
        assert_eq!(cast(Value::Currency(-12500)), Value::String("-1.25".into()));
        assert_eq!(cast(Value::Date(0.0)), Value::String("12:00:00 AM".into()));
        let lone_surrogate = Value::from_utf16(vec![0xd83d]);
        assert_eq!(cast(lone_surrogate.clone()), lone_surrogate);
    }

    #[test]
    fn automation_double_uses_vba_boolean_and_grouping_rules_and_typed_errors() {
        use super::{coerce_automation_scalar, host_error, AutomationScalarType, Value};
        let cast = |value| coerce_automation_scalar(&value, AutomationScalarType::Double);
        assert_eq!(cast(Value::Boolean(true)), Ok(Value::Double(-1.0)));
        assert_eq!(cast(Value::String("1,5".into())), Ok(Value::Double(15.0)));
        for (value, number, message) in [
            (Value::Null, 94, "Invalid use of Null"),
            (Value::Nothing, 91, "Object variable or With block variable not set"),
            (Value::Error(2007), 13, "Type mismatch"),
            (Value::String("True".into()), 13, "Type mismatch"),
        ] {
            assert_eq!(cast(value), Err(host_error(number, message)));
        }
    }

    use super::*;
    use crate::parse_module;

    #[derive(Default)]
    struct SheetHost {
        cells: BTreeMap<(u32, u32), Value>,
    }

    impl SheetHost {
        fn cell_object(row: u32, column: u32) -> Value {
            Value::Object(ObjectRef::new(((row as u64) << 32) | column as u64, "Cell"))
        }

        fn coordinates(object: &ObjectRef) -> Option<(u32, u32)> {
            (object.kind == "Cell").then_some(((object.handle >> 32) as u32, object.handle as u32))
        }
    }

    impl Host for SheetHost {
        fn call(
            &mut self,
            receiver: Option<&ObjectRef>,
            name: &str,
            args: &[Value],
        ) -> Result<Option<Value>, String> {
            if let Some(receiver) = receiver {
                if name.eq_ignore_ascii_case("offset") {
                    let Some((row, column)) = Self::coordinates(receiver) else {
                        return Ok(None);
                    };
                    let [row_offset, column_offset] = args else {
                        return Err("Offset expects row and column offsets".to_string());
                    };
                    let row = row as i64 + number(row_offset)?.round_ties_even() as i64;
                    let column = column as i64 + number(column_offset)?.round_ties_even() as i64;
                    if row < 1 || column < 1 {
                        return Err("Offset moved outside the sheet".to_string());
                    }
                    return Ok(Some(Self::cell_object(row as u32, column as u32)));
                }
                // A member whose refusal is Excel's error 5, not 1004.
                if name.eq_ignore_ascii_case("addcomment") {
                    return Err(host_error(5, "AddComment needs a single cell"));
                }
                return Ok(None);
            }
            if name.eq_ignore_ascii_case("range") || name.eq_ignore_ascii_case("evaluate") {
                let [Value::String(address)] = args else {
                    return Err(format!("{name} expects one A1 address"));
                };
                let address = address.to_ascii_uppercase();
                let column = address
                    .bytes()
                    .next()
                    .filter(u8::is_ascii_alphabetic)
                    .map(|value| (value - b'A' + 1) as u32)
                    .ok_or_else(|| "invalid Range address".to_string())?;
                let row = address[1..]
                    .parse::<u32>()
                    .map_err(|_| "invalid Range address".to_string())?;
                return Ok(Some(Self::cell_object(row, column)));
            }
            if name.eq_ignore_ascii_case("cells") {
                let [row, column] = args else {
                    return Err("Cells expects row and column".to_string());
                };
                let row = number(row)?.round_ties_even() as u32;
                let column = number(column)?.round_ties_even() as u32;
                return Ok(Some(Self::cell_object(row, column)));
            }
            Ok(None)
        }

        fn get(&mut self, receiver: &ObjectRef, name: &str) -> Result<Option<Value>, String> {
            let Some(coordinates) = Self::coordinates(receiver) else {
                return Ok(None);
            };
            if name.eq_ignore_ascii_case("value") {
                return Ok(Some(
                    self.cells
                        .get(&coordinates)
                        .cloned()
                        .unwrap_or(Value::Empty),
                ));
            }
            Ok(None)
        }

        fn set(&mut self, receiver: &ObjectRef, name: &str, value: Value) -> Result<bool, String> {
            let Some(coordinates) = Self::coordinates(receiver) else {
                return Ok(false);
            };
            if name.eq_ignore_ascii_case("value") {
                self.cells.insert(coordinates, value);
                return Ok(true);
            }
            Ok(false)
        }
    }


    /// Characterisation of the object-lifetime rules the runtime implements
    /// (the commits that added them carried their Excel measurements): when
    /// each Class_Terminate runs, relative to the statements around it.
    fn lifetime_log(body: &str) -> String {
        let source = format!(
            "Public Log As String
{body}
VERSION 1.0 CLASS
Attribute VB_Name = \"Grid\"
Private Sub Class_Initialize()
Log = Log & \"I\"
End Sub
Private Sub Class_Terminate()
Log = Log & \"T\"
End Sub
Public Sub Touch()
Log = Log & \"t\"
End Sub
"
        );
        let (module, classes) = crate::parser::parse_project(&source).unwrap();
        match Runtime::new(&module).with_classes(&classes).call("Main", vec![]) {
            Ok(Value::String(s)) => s,
            other => format!("{other:?}"),
        }
    }

    #[test]
    fn lifetime_rules_hold() {
        let cases: &[(&str, &str)] = &[
            ("set_nothing", "Function Main() As String
Dim g As Grid
Set g = New Grid
Log = Log & \"a\"
Set g = Nothing
Log = Log & \"b\"
Main = Log
End Function"),
            ("reassign", "Function Main() As String
Dim g As Grid
Set g = New Grid
Set g = New Grid
Log = Log & \"a\"
Set g = Nothing
Main = Log
End Function"),
            ("erase", "Function Main() As String
Dim a(1) As Grid
Set a(0) = New Grid
Set a(1) = New Grid
Log = Log & \"a\"
Erase a
Log = Log & \"b\"
Main = Log
End Function"),
            ("redim", "Function Main() As String
Dim a() As Grid
ReDim a(1)
Set a(0) = New Grid
Log = Log & \"a\"
ReDim a(2)
Log = Log & \"b\"
Main = Log
End Function"),
            ("collection", "Function Main() As String
Dim c As Collection
Set c = New Collection
c.Add New Grid
c.Add New Grid
Log = Log & \"a\"
Set c = Nothing
Log = Log & \"b\"
Main = Log
End Function"),
            ("collection_remove", "Function Main() As String
Dim c As Collection
Set c = New Collection
c.Add New Grid
Log = Log & \"a\"
c.Remove 1
Log = Log & \"b\"
Main = Log
End Function"),
            ("dictionary", "Function Main() As String
Dim d As Object
Set d = CreateObject(\"Scripting.Dictionary\")
d.Add \"k\", New Grid
Log = Log & \"a\"
Set d = Nothing
Log = Log & \"b\"
Main = Log
End Function"),
            ("left_by_error", "Sub P()
Dim g As Grid
Set g = New Grid
Err.Raise 5
End Sub
Function Main() As String
On Error Resume Next
P
Log = Log & \"e\" & Err.Number
Main = Log
End Function"),
            ("as_new", "Function Main() As String
Dim g As New Grid
g.Touch
Set g = Nothing
Log = Log & \"a\"
g.Touch
Log = Log & \"b\"
Main = Log
End Function"),
            ("discarded_result", "Function Make() As Grid
Set Make = New Grid
End Function
Function Main() As String
Make
Log = Log & \"a\"
Main = Log
End Function"),
            ("nested_holder", "Function Main() As String
Dim c As Collection
Set c = New Collection
Dim inner As Collection
Set inner = New Collection
inner.Add New Grid
c.Add inner
Set inner = Nothing
Log = Log & \"a\"
Set c = Nothing
Log = Log & \"b\"
Main = Log
End Function"),
        ];
        let got: Vec<(String, String)> = cases.iter().map(|(n, b)| (n.to_string(), lifetime_log(b))).collect();
        if std::env::var_os("LIFETIME_PRINT").is_some() {
            for (n, g) in &got { eprintln!("LIFETIME {n} = {g}"); }
        }
        let expected: &[(&str, &str)] = EXPECTED_LIFETIME;
        for ((n, g), (en, e)) in got.iter().zip(expected) {
            assert_eq!((n.as_str(), g.as_str()), (*en, *e));
        }
    }

    const EXPECTED_LIFETIME: &[(&str, &str)] = &[("set_nothing", "IaTb"), ("reassign", "IITaT"), ("erase", "IIaTTb"), ("redim", "IaTb"), ("collection", "IIaTTb"), ("collection_remove", "IaTb"), ("dictionary", "IaTb"), ("left_by_error", "ITe5"), ("as_new", "ItTaItb"), ("discarded_result", "ITa"), ("nested_holder", "IaTb")];

    /// Two instances let go together are each terminated once: the first
    /// one's Class_Terminate collects the second on its own return, and the
    /// loop that started it must not then go looking for the second's
    /// Class_Terminate in the standard module. Measured in Excel: the
    /// function's answer stands and both terminate after it.
    #[test]
    fn two_instances_let_go_together_terminate_once_each() {
        let source = "Public Log As String
Function Inner() As String
Dim g As Grid, h As Grid
Set g = New Grid
Set h = New Grid
Inner = \"z\" & Log
End Function
Function Main() As String
Main = Inner() & \"#\" & Log
End Function
VERSION 1.0 CLASS
Attribute VB_Name = \"Grid\"
Private Sub Class_Initialize()
Log = Log & \"I\"
End Sub
Private Sub Class_Terminate()
Log = Log & \"T\"
End Sub
";
        let (module, classes) = crate::parser::parse_project(source).unwrap();
        let answer = Runtime::new(&module).with_classes(&classes).call("Main", vec![]);
        assert_eq!(answer.unwrap(), Value::String("zII#IITT".to_string()));
    }

    /// No VBA function brings the runtime down, however odd what it is
    /// handed: each is called with nothing and with one to four of the same
    /// odd value, under On Error Resume Next, and must answer or raise.
    #[test]
    fn no_builtin_panics_on_odd_arguments() {
        const NAMES: &[&str] = &["abs", "array", "asc", "ascb", "ascw", "atn", "callbyname", "cbool", "cbyte", "ccur", "cdate", "cdbl", "cdec", "choose", "chr", "chr$", "chrb", "chrb$", "chrw", "cint", "clng", "clnglng", "clngptr", "cos", "csng", "cstr", "cvar", "cvdate", "cverr", "date", "date$", "dateadd", "datediff", "datepart", "dateserial", "datevalue", "day", "ddb", "environ", "environ$", "error", "error$", "exp", "filter", "fix", "format", "format$", "formatcurrency", "formatdatetime", "formatnumber", "formatpercent", "freefile", "fv", "hex", "hex$", "hour", "iif", "instr", "instrb", "instrrev", "int", "ipmt", "irr", "isarray", "isdate", "isempty", "iserror", "ismissing", "isnull", "isnumeric", "isobject", "join", "lbound", "lcase", "lcase$", "left", "left$", "leftb", "len", "lenb", "log", "ltrim", "mid", "mid$", "midb", "minute", "mirr", "month", "monthname", "now", "nper", "npv", "objptr", "oct", "oct$", "partition", "pmt", "ppmt", "pv", "qbcolor", "rate", "replace", "rgb", "right", "right$", "rightb", "rnd", "round", "rtrim", "second", "sgn", "sin", "sln", "space", "space$", "split", "sqr", "str", "str$", "strcomp", "strconv", "string", "string$", "strptr", "strreverse", "switch", "syd", "tan", "time", "time$", "timer", "timeserial", "timevalue", "trim", "trim$", "typename", "ubound", "ucase", "ucase$", "val", "varptr", "vartype", "weekday", "weekdayname", "year"];
        const KINDS: &[&str] = &[
            "\"\"", "\"abc\"", "Empty", "Null", "True", "-1", "0", "0.5", "1E+300", "-1E+300",
            "1E+10", "2147483648#", "1000000000", "-2147483648#", "32768", "-32769", "#12/31/9999 11:59:59 PM#", "CDec(\"79228162514264337593543950335\")", "\"\"", "Array()", "Array(1, \"x\")", "CVErr(5)", "#1/1/100#", "Nothing",
        ];
        let mut fell: Vec<String> = Vec::new();
        for name in NAMES {
            for kind in KINDS {
                let mut body = String::from("Public Function Probe() As Variant
On Error Resume Next
Dim x As Variant
");
                for count in 0..=4 {
                    let args = vec![*kind; count].join(", ");
                    if count == 0 {
                        body.push_str(&format!("x = {name}()
"));
                    } else {
                        body.push_str(&format!("x = {name}({args})
"));
                    }
                }
                body.push_str("End Function
");
                let Ok(module) = parse_module(&body) else {
                    continue;
                };
                let caught = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    let mut runtime = Runtime::new(&module);
                    runtime.max_steps = 200_000;
                    let _ = runtime.call("Probe", vec![]);
                }));
                if caught.is_err() {
                    fell.push(format!("{name}({kind})"));
                }
            }
        }
        assert!(fell.is_empty(), "panicked ({}): {}", fell.len(), fell.join(" "));
    }

    fn run(source: &str, name: &str, args: Vec<Value>) -> Result<Value, RuntimeError> {
        let module = parse_module(source).unwrap();
        execute(&module, name, args)
    }

    /// A `Type ... End Type` variable, as Excel answers for each of these.
    ///
    /// Excel cannot be asked what `TypeName` makes of the record ITSELF --
    /// handing one to a Variant parameter is a compile error there -- so only
    /// the fields are measured, and each reads back as the type it was
    /// declared with.
    #[test]
    fn a_user_type_holds_its_fields() {
        let source = "Public Type Point\n\
                        x As Long\n\
                        label As String\n\
                      End Type\n\
                      Public Function Ask() As String\n\
                        Dim spot As Point\n\
                        spot.x = 3\n\
                        spot.label = \"here\"\n\
                        Ask = spot.x & \"/\" & spot.label\n\
                      End Function\n";
        assert_eq!(
            run(source, "Ask", vec![]).unwrap(),
            Value::String("3/here".to_string())
        );
    }

    /// Records are copied, not shared: Excel answers `1/99`.
    #[test]
    fn a_user_type_is_copied_on_assignment() {
        let source = "Public Type Point\n\
                        x As Long\n\
                      End Type\n\
                      Public Function Ask() As String\n\
                        Dim first As Point\n\
                        Dim second As Point\n\
                        first.x = 1\n\
                        second = first\n\
                        second.x = 99\n\
                        Ask = first.x & \"/\" & second.x\n\
                      End Function\n";
        assert_eq!(
            run(source, "Ask", vec![]).unwrap(),
            Value::String("1/99".to_string())
        );
    }

    #[test]
    fn a_user_type_names_its_fields() {
        let source = "Public Type Point\n\
                        x As Long\n\
                        label As String\n\
                      End Type\n\
                      Public Function Ask() As String\n\
                        Dim spot As Point\n\
                        Ask = TypeName(spot.x) & \"/\" & TypeName(spot.label)\n\
                      End Function\n";
        assert_eq!(
            run(source, "Ask", vec![]).unwrap(),
            Value::String("Long/String".to_string())
        );
    }

