    /// Which number a Collection subscript raises, as Excel raises it.
    #[test]
    fn a_collection_subscript_out_of_range() {
        let ask = |body: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim box As New Collection\n\
                   Dim complaint As Long\n\
                   Dim answer As Variant\n\
                   {body}\n\
                   Ask = \"err\" & complaint\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        let attempt = "On Error Resume Next\n\
                       answer = box(INDEX)\n\
                       complaint = Err.Number\n\
                       On Error GoTo 0";
        let two = format!("box.Add \"a\"\nbox.Add \"b\"\n{attempt}");
        // Out of range over entries that exist is 9.
        assert_eq!(ask(&two.replace("INDEX", "0")), "err9");
        assert_eq!(ask(&two.replace("INDEX", "3")), "err9");
        assert_eq!(ask(&two.replace("INDEX", "-1")), "err9");
        // A collection with nothing in it answers 5 to every number.
        assert_eq!(ask(&attempt.replace("INDEX", "0")), "err5");
        assert_eq!(ask(&attempt.replace("INDEX", "1")), "err5");
        assert_eq!(ask(&attempt.replace("INDEX", "5")), "err5");
        // A key that is not there is 5, and text is always a key.
        assert_eq!(ask(&two.replace("INDEX", "\"missing\"")), "err5");
        assert_eq!(ask(&two.replace("INDEX", "\"2\"")), "err5");
    }

    /// A fractional subscript is made whole first, half to the even side.
    #[test]
    fn a_fractional_collection_subscript() {
        let source = "Public Function Ask() As String\n\
                        Dim box As New Collection\n\
                        box.Add \"a\"\n\
                        box.Add \"b\"\n\
                        Ask = box(1.4) & box(0.6) & box(1.5) & box(1.7) & box(2.4)\n\
                      End Function\n";
        assert_eq!(
            run(source, "Ask", vec![]).unwrap(),
            Value::String("aabbb".to_string())
        );
    }

    /// Remove and `Add Before` read a subscript the same way Item does.
    #[test]
    fn removing_by_a_subscript_that_is_not_there() {
        let ask = |body: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim box As New Collection\n\
                   Dim complaint As Long\n\
                   box.Add \"a\", \"first\"\n\
                   On Error Resume Next\n\
                   {body}\n\
                   complaint = Err.Number\n\
                   On Error GoTo 0\n\
                   Ask = \"err\" & complaint & \"/\" & box.Count\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        assert_eq!(ask("box.Remove 5"), "err9/1");
        assert_eq!(ask("box.Remove 0"), "err9/1");
        assert_eq!(ask("box.Remove \"missing\""), "err5/1");
        assert_eq!(ask("box.Add \"b\", , 9"), "err9/1");
    }

    /// What a `Like` pattern Excel refuses looks like, and — just as much of
    /// the rule — when it declines to refuse it.
    ///
    /// Both faults are judged LAZILY, only where the match arrives at the set:
    /// `"b" Like "[a-c][x"` is False and raises nothing, because after `[a-c]`
    /// has taken the only character there is nothing left to test `[x`
    /// against. Put a star in front of the same set and it is reached, and
    /// raises.
    #[test]
    fn a_like_pattern_excel_refuses() {
        let ask = |subject: &str, pattern: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim complaint As Long\n\
                   Dim answer As Variant\n\
                   On Error Resume Next\n\
                   answer = \"{subject}\" Like \"{pattern}\"\n\
                   complaint = Err.Number\n\
                   On Error GoTo 0\n\
                   Ask = \"[\" & answer & \"]/err\" & complaint\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        // A range written backwards, and a set nobody closed.
        assert_eq!(ask("a", "[c-a]"), "[]/err93");
        assert_eq!(ask("b", "[b-a]"), "[]/err93");
        assert_eq!(ask("a", "[abc"), "[]/err93");
        assert_eq!(ask("[", "["), "[]/err93");
        // Reached through a star or a question mark, and still refused.
        assert_eq!(ask("b", "*[x"), "[]/err93");
        assert_eq!(ask("abc", "*[c-a]"), "[]/err93");
        assert_eq!(ask("abc", "?[c-a]"), "[]/err93");
        assert_eq!(ask("ab", "[a-c][c-a]"), "[]/err93");
        // Never reached, so never refused.
        assert_eq!(ask("b", "[a-c][x"), "[False]/err0");
        assert_eq!(ask("b", "[a-c][z-x]"), "[False]/err0");
        assert_eq!(ask("", "[c-a]"), "[False]/err0");
        assert_eq!(ask("", "[x"), "[False]/err0");
        assert_eq!(ask("a", "a*[c-a]"), "[False]/err0");
        // A set is walked in order and stops at the first range that holds the
        // character, so a good range in front of a bad one hides it.
        assert_eq!(ask("a", "[a-cz-x]"), "[True]/err0");
        assert_eq!(ask("y", "[z-xa-c]"), "[]/err93");
    }

    /// An empty set is NOT refused: it matches no characters at all.
    #[test]
    fn a_like_pattern_with_an_empty_set() {
        let ask = |subject: &str, pattern: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Ask = CStr(\"{subject}\" Like \"{pattern}\")\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        assert_eq!(ask("", "[]"), "True");
        assert_eq!(ask("a", "[]"), "False");
        assert_eq!(ask("ab", "a[]b"), "True");
        assert_eq!(ask("ab", "ab[]"), "True");
        // The `!` only turns a set over while something follows it.
        assert_eq!(ask("!", "[!]"), "True");
        assert_eq!(ask("a", "[!]"), "False");
        assert_eq!(ask("a", "[!!]"), "True");
        assert_eq!(ask("!", "[!!]"), "False");
        // A set ends at the first `]`, so `[[]` holds an opening bracket.
        assert_eq!(ask("[", "[[]"), "True");
        assert_eq!(ask("a", "[[]"), "False");
    }

    /// The question a reader of somebody else's macros keeps asking, and the
    /// one a host has to answer before it can say what it must supply.
    /// A Boolean reaches Byte by its BITS; everything else by its value.
    ///
    /// Found by a generated case and then asked of Excel in nine shapes, which
    /// is what separates the rule from the one case: `CByte(-1)` overflows
    /// just as it did before, so "True is -1, and -1 is 255" would have been
    /// the wrong law.
    /// What a number written in source IS.
    ///
    /// Asked of Excel across fifteen shapes. The one that reads oddly is
    /// `-32768`, which is a Long: the minus is an operator applied to `32768`,
    /// and that is already past what an Integer holds.
    #[test]
    fn a_written_number_takes_the_smallest_type_that_holds_it() {
        let kind = |expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n  Ask = CStr(VarType({expression}))\nEnd Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        // 2 Integer, 3 Long, 4 Single, 5 Double, 6 Currency, 7 Date, 17 Byte
        assert_eq!(kind("1"), "2");
        assert_eq!(kind("32767"), "2");
        assert_eq!(kind("32768"), "3");
        assert_eq!(kind("2147483647"), "3");
        assert_eq!(kind("2147483648"), "5");
        assert_eq!(kind("-32768"), "3");
        assert_eq!(kind("1.5"), "5");
        // An exponent is a Double even where the number is whole.
        assert_eq!(kind("1E15"), "5");
        // A type character says it outright.
        assert_eq!(kind("1%"), "2");
        assert_eq!(kind("1&"), "3");
        assert_eq!(kind("1!"), "4");
        assert_eq!(kind("1#"), "5");
        assert_eq!(kind("1@"), "6");
        assert_eq!(kind("#1/2/2003#"), "7");
    }

    /// A declared variable keeps its declared type, and so does what a
    /// procedure declares it returns.
    #[test]
    fn a_declared_variable_keeps_its_type() {
        let source = "Public Function Ask() As String\n\
                        Dim aByte As Byte\n\
                        Dim anInteger As Integer\n\
                        Dim aLong As Long\n\
                        Dim aSingle As Single\n\
                        Dim aDouble As Double\n\
                        Dim aCurrency As Currency\n\
                        Dim aDate As Date\n\
                        Ask = VarType(aByte) & \"/\" & VarType(anInteger) & \"/\" & \
                              VarType(aLong) & \"/\" & VarType(aSingle) & \"/\" & \
                              VarType(aDouble) & \"/\" & VarType(aCurrency) & \"/\" & \
                              VarType(aDate)\n\
                      End Function\n";
        assert_eq!(
            run(source, "Ask", vec![]).unwrap(),
            Value::String("17/2/3/4/5/6/7".to_string())
        );
    }

    /// Arithmetic takes the higher of the two types and OVERFLOWS rather than
    /// widening — the single most consequential thing here, because a
    /// `Dim i As Integer` that a macro walks past 32767 is meant to stop.
    ///
    /// The ladder is not simply "widest wins": Currency beats Double, and a
    /// Date beats anything that is not a Date while two Dates give the plain
    /// number of days between them. All measured against Excel.
    #[test]
    fn arithmetic_takes_the_higher_type_and_overflows() {
        let kind = |setup: &str, expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim aByte As Byte\n\
                   Dim anInteger As Integer\n\
                   Dim aLong As Long\n\
                   Dim aSingle As Single\n\
                   Dim aDouble As Double\n\
                   Dim aCurrency As Currency\n\
                   Dim aDate As Date\n\
                   Dim answer As Variant\n\
                   On Error Resume Next\n\
                   {setup}\n\
                   answer = {expression}\n\
                   If Err.Number <> 0 Then\n\
                     Ask = \"err\" & Err.Number\n\
                   Else\n\
                     Ask = CStr(VarType(answer))\n\
                   End If\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        let plain = "aByte = 1: anInteger = 300: aLong = 32767: aSingle = 1.5: \
                     aDouble = 1.5: aCurrency = 1.5: aDate = #1/2/2003#";

        assert_eq!(kind(plain, "1 + 1"), "2");
        assert_eq!(kind(plain, "aByte + aByte"), "17");
        assert_eq!(kind(plain, "aByte + anInteger"), "2");
        assert_eq!(kind(plain, "aLong + anInteger"), "3");
        assert_eq!(kind(plain, "aSingle + anInteger"), "4");
        assert_eq!(kind(plain, "aSingle + aDouble"), "5");
        // Currency wins against Double, which the ladder alone would not say.
        assert_eq!(kind(plain, "aCurrency + aDouble"), "6");
        // A Date wins against anything that is not one; two of them do not.
        assert_eq!(kind(plain, "aDate + 1"), "7");
        assert_eq!(kind(plain, "aDate - aDate"), "5");
        // Division and powers are Double whatever they were given.
        assert_eq!(kind(plain, "1 / 2"), "5");
        assert_eq!(kind(plain, "4 / 2"), "5");
        assert_eq!(kind(plain, "2 ^ 2"), "5");
        assert_eq!(kind(plain, "aByte / aByte"), "5");
        // Integer division and Mod keep a whole type.
        assert_eq!(kind(plain, "5 \\ 2"), "2");
        assert_eq!(kind(plain, "5 Mod 2"), "2");
        // Empty never lifts the answer.
        assert_eq!(kind(plain, "Empty + 1"), "2");
        // A sign keeps the type it was put in front of.
        assert_eq!(kind(plain, "-1"), "2");

        // And what does NOT happen: widening.
        assert_eq!(kind(plain, "32767 + 1"), "err6");
        assert_eq!(kind(plain, "2147483647 + 1"), "err6");
        assert_eq!(kind(plain, "anInteger * anInteger"), "err6");
        assert_eq!(kind("aByte = 200", "aByte + aByte"), "err6");
    }

    /// How wide `Hex` and `Oct` write a negative number follows the TYPE they
    /// were given, not the number.
    ///
    /// Found twice over by generated cases and then asked of Excel across the
    /// types: `Hex(-2)` is four digits because `2` is an Integer, a Long is
    /// eight, and anything that arrives as a Double — including every number
    /// read out of a cell — is sixteen. Only tellable once the interpreter
    /// keeps the types apart.
    /// What a `Format` picture asks for, measured against Excel over four
    /// values and every shape of picture below.
    ///
    /// The engine before this counted the digits AFTER the point and merely
    /// asked whether there was a `0` before it, so `Format(-0.5, "000")`
    /// answered `-0` instead of `-001` and no literal in a picture was ever
    /// written at all.
    /// Which of Format's two languages a picture is written in, and the
    /// surprise that settles it: the FIRST placeholder or date code wins, not
    /// merely the presence of one.
    #[test]
    fn a_picture_is_read_in_the_language_its_first_code_names() {
        let ask = |value: &str, picture: &str| {
            let source = format!(
                "Public Function Ask() As String\n  Ask = Format({value}, \"{picture}\")\nEnd Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };

        // -0.5 is noon on day zero: the thirtieth of December 1899.
        assert_eq!(ask("-0.5", "ad"), "a30");
        assert_eq!(ask("-0.5", "as"), "a0");
        assert_eq!(ask("-0.5", "ah"), "a12");
        assert_eq!(ask("-0.5", "ay"), "a364");
        assert_eq!(ask("-0.5", "aq"), "a4");
        assert_eq!(ask("-0.5", "aw"), "a7");
        assert_eq!(ask("-0.5", "ac"), "a12:00:00 PM");

        // A single `s` is enough, which is the whole of why this answers so
        // oddly: the s is seconds and the rest are just characters.
        assert_eq!(ask("-0.5", "False"), "Fal0e");
        // No code and no placeholder at all: written out, with the sign.
        assert_eq!(ask("-0.5", "True"), "-True");
        assert_eq!(ask("-0.5", "abz"), "-abz");

        // The first one wins. `0 yen` holds a y and an n and is still a
        // number; `JPY 0` is a date, and its 0 is then just a character.
        assert_eq!(ask("-0.5", "0 yen"), "-1 yen");
        assert_eq!(ask("-0.5", "JPY 0"), "JP364 0");
        assert_eq!(ask("-0.5", "a0z"), "-a1z");

        // The named formats are matched before any of this, or Currency would
        // be read as a date for its c and Fixed for its d.
        assert_eq!(ask("1234.567", "Fixed"), "1234.57");
        assert_eq!(ask("1234.567", "Standard"), "1,234.57");
        assert_eq!(ask("0", "Yes/No"), "No");
        assert_eq!(ask("1", "True/False"), "True");
    }

    /// A serial keeps its date whole and its time fractional, and the fraction
    /// is a time of day on either side of zero.
    #[test]
    fn a_negative_serial_is_a_time_on_its_own_day() {
        let ask = |value: &str, picture: &str| {
            let source = format!(
                "Public Function Ask() As String\n  Ask = Format({value}, \"{picture}\")\nEnd Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        // Noon on day zero, not midnight on day minus one.
        assert_eq!(ask("-0.5", "c"), "12:00:00 PM");
        assert_eq!(ask("-1234.5", "c"), "8/13/1896 12:00:00 PM");
        assert_eq!(ask("-1234.5", "ad"), "a13");
        assert_eq!(ask("-1234.5", "aw"), "a5");
        // Neither a day nor a time is still written as a time.
        assert_eq!(ask("0", "c"), "12:00:00 AM");
        // Positive serials are unmoved.
        assert_eq!(ask("1234.567", "c"), "5/18/1903 1:36:29 PM");
        assert_eq!(ask("1234.567", "ad"), "a18");
    }

    #[test]
    fn a_number_written_the_way_its_picture_asks() {
        let ask = |value: &str, picture: &str| {
            let source = format!(
                "Public Function Ask() As String\n  Ask = Format({value}, \"{picture}\")\nEnd Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };

        // `0` is always written, `#` is dropped where it would be a leading or
        // trailing zero — so a zero written with hashes is nothing at all.
        assert_eq!(ask("-0.5", "000"), "-001");
        assert_eq!(ask("-0.5", "0"), "-1");
        assert_eq!(ask("-0.5", "###"), "-1");
        assert_eq!(ask("0", "000"), "000");
        assert_eq!(ask("0", "###"), "");
        assert_eq!(ask("0", "#0"), "0");
        assert_eq!(ask("0", "#.##"), ".");
        assert_eq!(ask("1234.567", "000"), "1235");

        // Rounded away from zero, to as many decimals as the picture asks.
        assert_eq!(ask("-1234.5", "0"), "-1235");
        assert_eq!(ask("1234.567", "0.0"), "1234.6");
        assert_eq!(ask("1234.567", "0.00"), "1234.57");

        // Grouping, percent, and the exponent.
        assert_eq!(ask("-1234.5", "#,##0"), "-1,235");
        assert_eq!(ask("-0.5", "0%"), "-50%");
        assert_eq!(ask("1234.567", "0E+00"), "1E+03");
        assert_eq!(ask("-0.5", "0E+00"), "-5E-01");
        assert_eq!(ask("0", "0E+00"), "0E+00");
        assert_eq!(ask("-0.5", "0e+00"), "-5e-01");

        // Sections: positive; negative; zero. A negative with a section of its
        // own carries no minus, and an empty section counts as absent.
        assert_eq!(ask("-1234.5", "0;(0)"), "(1235)");
        assert_eq!(ask("1234.567", "0;(0)"), "1235");
        assert_eq!(ask("0", "0;(0);zero"), "zero");
        assert_eq!(ask("-0.5", "0;"), "-1");

        // Literals, and the minus in front of the WHOLE answer.
        assert_eq!(ask("-0.5", "0 yen"), "-1 yen");
        assert_eq!(ask("-0.5", "\\0 0"), "-0 1");
        assert_eq!(ask("1234.567", "\\0 0"), "0 1235");
    }

    #[test]
    fn hex_and_oct_write_as_wide_as_their_argument() {
        let ask = |setup: &str, expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim anInteger As Integer\n\
                   Dim aLong As Long\n\
                   Dim aByte As Byte\n\
                   Dim aCurrency As Currency\n\
                   {setup}\n\
                   Ask = CStr({expression})\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        let plain = "anInteger = 2: aLong = 70000: aByte = 2: aCurrency = 2";
        assert_eq!(ask(plain, "Hex(anInteger)"), "2");
        assert_eq!(ask(plain, "Hex(-anInteger)"), "FFFE");
        assert_eq!(ask(plain, "Hex(aLong)"), "11170");
        assert_eq!(ask(plain, "Hex(-aLong)"), "FFFEEE90");
        assert_eq!(ask(plain, "Hex(-2)"), "FFFE");
        assert_eq!(ask(plain, "Hex(-2.5)"), "FFFFFFFFFFFFFFFE");
        assert_eq!(ask(plain, "Hex(-aCurrency)"), "FFFFFFFFFFFFFFFE");
        assert_eq!(ask(plain, "Oct(-2)"), "177776");
        assert_eq!(ask(plain, "Oct(-2.5)"), "1777777777777777777776");
    }

    /// `Round` reads the number of places BEFORE it looks at the value, and
    /// puts no ceiling on them.
    /// `Round` keeps the type it was handed, and its places reach 22.
    ///
    /// Both numbers here were got wrong first by generalising from one
    /// measurement: 16 places working was read as "no ceiling", and a Date
    /// surviving was read as "keeps the type" before a Single had been asked.
    /// The second guess turned out right and the first did not.
    /// DatePart judges its interval before it looks at the date, so a name
    /// that is not an interval is a bad argument rather than whatever the date
    /// turns out to be.
    #[test]
    fn datepart_judges_its_interval_first() {
        let ask = |expression: &str| {
            let source = format!(
                "Public Function Ask() As String
                   Dim answer As Variant
                   On Error Resume Next
                   answer = {expression}
                   If Err.Number <> 0 Then
                     Ask = \"err\" & Err.Number
                   Else
                     Ask = CStr(answer)
                   End If
                 End Function
"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        assert_eq!(ask("DatePart(2, \"ABC\")"), "err5");
        assert_eq!(ask("DatePart(2, 1)"), "err5");
        assert_eq!(ask("DatePart(\"d\", \"ABC\")"), "err13");
        assert_eq!(ask("DatePart(\"d\", #1/2/2003#)"), "2");
    }

    #[test]
    fn round_keeps_its_type_and_stops_at_twenty_two_places() {
        let ask = |setup: &str, expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim aSingle As Single\n\
                   Dim aDouble As Double\n\
                   Dim anInteger As Integer\n\
                   Dim aLong As Long\n\
                   Dim aCurrency As Currency\n\
                   Dim aDate As Date\n\
                   Dim answer As Variant\n\
                   On Error Resume Next\n\
                   {setup}\n\
                   answer = {expression}\n\
                   If Err.Number <> 0 Then\n\
                     Ask = \"err\" & Err.Number\n\
                   Else\n\
                     Ask = CStr(answer)\n\
                   End If\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        let plain = "aSingle = 0.7055475: aDouble = 0.7055475: anInteger = 2: \
                     aLong = 2: aCurrency = 1.5: aDate = #1/2/2003#";

        // 2 Integer, 3 Long, 4 Single, 5 Double, 6 Currency, 7 Date
        assert_eq!(ask(plain, "VarType(Round(aSingle, 2))"), "4");
        assert_eq!(ask(plain, "VarType(Round(aDouble, 2))"), "5");
        assert_eq!(ask(plain, "VarType(Round(anInteger, 2))"), "2");
        assert_eq!(ask(plain, "VarType(Round(aCurrency, 2))"), "6");
        assert_eq!(ask(plain, "VarType(Round(aDate, 2))"), "7");
        assert_eq!(ask(plain, "VarType(Round(2, 2))"), "2");

        // The ceiling is 22, not 15 and not absent.
        assert_eq!(ask(plain, "Round(1.5, 22)"), "1.5");
        assert_eq!(ask(plain, "Round(1.5, 23)"), "err5");
    }

    /// A Single says only as many digits as a Single holds.
    ///
    /// Widening it to a Double first turns 0.7055475 into
    /// 0.705547511577606. Nothing caught this until `Round` began handing
    /// Singles back.
    #[test]
    fn a_single_says_only_what_a_single_holds() {
        let source = "Public Function Ask() As String\n\
                        Dim aSingle As Single\n\
                        aSingle = 0.7055475\n\
                        Ask = CStr(aSingle) & \"/\" & CStr(Round(aSingle, 7))\n\
                      End Function\n";
        assert_eq!(
            run(source, "Ask", vec![]).unwrap(),
            Value::String("0.7055475/0.7055475".to_string())
        );
    }

    /// A Date says itself as a date, and Empty says nothing whatever picture
    /// it is given.
    #[test]
    fn a_date_says_itself_as_a_date() {
        let source = "Public Function Ask() As String\n\
                        Ask = CStr(#1/2/2003#) & \"|\" & CStr(#12:00:00 PM#) & \"|\" & \
                              CStr(#1/2/2003 3:04:05 PM#) & \"|\" & (#1/2/2003# & \"\") & \"|\" & \
                              \"[\" & Format(Empty, \"000\") & \"]\" & \"[\" & Format(Empty, \"abz\") & \"]\"\n\
                      End Function\n";
        assert_eq!(
            run(source, "Ask", vec![]).unwrap(),
            Value::String(
                "1/2/2003|12:00:00 PM|1/2/2003 3:04:05 PM|1/2/2003|[][]".to_string()
            )
        );
    }

    #[test]
    fn round_judges_its_places_first() {
        let ask = |expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim answer As Variant\n\
                   On Error Resume Next\n\
                   answer = {expression}\n\
                   If Err.Number <> 0 Then\n\
                     Ask = \"err\" & Err.Number\n\
                   Else\n\
                     Ask = CStr(answer)\n\
                   End If\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        // Places out of range wins over a value that is not a number.
        assert_eq!(ask("Round(vbNullString, -2.5)"), "err5");
        assert_eq!(ask("Round(1.5, -1)"), "err5");
        // With the places in order, the value is judged next.
        assert_eq!(ask("Round(vbNullString, 2)"), "err13");
        assert_eq!(ask("Round(1.5, \"x\")"), "err13");
        // And there is no upper bound on the places.
        assert_eq!(ask("Round(1.5, 16)"), "1.5");
        assert_eq!(ask("Round(Empty, 2)"), "0");
    }

    /// An empty String will not convert to a Boolean, though `Empty` will.
    #[test]
    fn cbool_refuses_an_empty_string() {
        let ask = |expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim answer As Variant\n\
                   On Error Resume Next\n\
                   answer = {expression}\n\
                   If Err.Number <> 0 Then\n\
                     Ask = \"err\" & Err.Number\n\
                   Else\n\
                     Ask = CStr(answer)\n\
                   End If\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        assert_eq!(ask("CBool(\"\")"), "err13");
        assert_eq!(ask("CBool(Empty)"), "False");
        assert_eq!(ask("CBool(\"abc\")"), "err13");
        assert_eq!(ask("CBool(\"1\")"), "True");
    }

    /// A Null anywhere in `InStr` wins over a start position out of range.
    #[test]
    fn instr_answers_null_before_it_refuses_a_start() {
        let ask = |expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim answer As Variant\n\
                   On Error Resume Next\n\
                   answer = {expression}\n\
                   If Err.Number <> 0 Then\n\
                     Ask = \"err\" & Err.Number\n\
                   Else\n\
                     Ask = TypeName(answer)\n\
                   End If\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        // The same bad start, with and without a Null beside it.
        assert_eq!(ask("InStr(False, False, Null)"), "Null");
        assert_eq!(ask("InStr(0, \"abc\", \"b\")"), "err5");
        assert_eq!(ask("InStr(1, \"abc\", Null)"), "Null");
        assert_eq!(ask("InStr(1, Null, \"b\")"), "Null");
        assert_eq!(ask("InStr(Null, \"abc\", \"b\")"), "err94");
    }

    #[test]
    fn a_boolean_reaches_byte_by_its_bits() {
        let ask = |expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim answer As Variant\n\
                   On Error Resume Next\n\
                   answer = {expression}\n\
                   If Err.Number <> 0 Then\n\
                     Ask = \"err\" & Err.Number\n\
                   Else\n\
                     Ask = CStr(answer)\n\
                   End If\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        assert_eq!(ask("CByte(True)"), "255");
        assert_eq!(ask("CByte(False)"), "0");
        assert_eq!(ask("CByte(-1)"), "err6");
        assert_eq!(ask("CByte(255)"), "255");
        assert_eq!(ask("CByte(256)"), "err6");
        assert_eq!(ask("CByte(255.5)"), "err6");
        // Half to the even side, as everywhere else.
        assert_eq!(ask("CByte(0.5)"), "0");
        assert_eq!(ask("CByte(1.5)"), "2");
        assert_eq!(ask("CByte(\"12\")"), "12");
    }

    /// An empty needle answers with the start position itself.
    #[test]
    fn instrrev_with_an_empty_needle() {
        let ask = |expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n  Ask = CStr({expression})\nEnd Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        assert_eq!(ask("InStrRev(\"abcd\", \"\")"), "4");
        assert_eq!(ask("InStrRev(\"abcd\", \"\", 2)"), "2");
        assert_eq!(ask("InStrRev(\"\", \"\")"), "0");
        // A needle that is there keeps the one-based answer it always gave.
        assert_eq!(ask("InStrRev(\"abcd\", \"c\")"), "3");
        assert_eq!(ask("InStrRev(\"abcd\", \"a\")"), "1");
        assert_eq!(ask("InStrRev(\"abcd\", \"z\")"), "0");
    }

    /// Mid makes every argument a number before it judges any of them, so an
    /// argument that is not a number is a type mismatch even when another
    /// argument is also out of range, and a start past the end of the string
    /// no longer hides a third argument nobody looked at.
    #[test]
    fn mid_judges_its_arguments_in_excels_order() {
        let ask = |expression: &str| {
            let source = format!(
                "Public Function Ask() As String\n\
                   Dim answer As Variant\n\
                   Dim things As Variant\n\
                   things = Array(1, 2)\n\
                   On Error Resume Next\n\
                   answer = {expression}\n\
                   If Err.Number <> 0 Then\n\
                     Ask = \"err\" & Err.Number\n\
                   Else\n\
                     Ask = \"[\" & CStr(answer) & \"]\"\n\
                   End If\n\
                 End Function\n"
            );
            match run(&source, "Ask", vec![]) {
                Ok(Value::String(answer)) => answer,
                other => panic!("{other:?}"),
            }
        };
        assert_eq!(ask("Mid(-1, -1, \" a \")"), "err13");
        assert_eq!(ask("Mid(0, 32767, things)"), "err13");
        assert_eq!(ask("Mid(\"abc\", 0)"), "err5");
        assert_eq!(ask("Mid(\"abc\", -1)"), "err5");
        assert_eq!(ask("Mid(\"abc\", 1, -1)"), "err5");
        // What it always did, kept.
        assert_eq!(ask("Mid(\"abcdef\", 2, 3)"), "[bcd]");
        assert_eq!(ask("Mid(\"abc\", 9)"), "[]");
    }

    #[test]
    fn the_language_is_told_apart_from_the_host() {
        // VBA's own, so they work with no workbook underneath.
        for name in ["Left", "CStr", "IsNumeric", "Split", "Format", "Round"] {
            assert!(is_builtin_function(name), "{name} is VBA's own");
        }
        // Matched the way VBA matches it.
        assert!(is_builtin_function("lEfT"));
        // Excel's, so a host has to supply them.
        for name in ["Cells", "Range", "Worksheets", "ActiveSheet", "Selection"] {
            assert!(!is_builtin_function(name), "{name} is the host's");
        }
        // A control, so a test that passed by saying yes to everything fails.
        assert!(!is_builtin_function("NotAFunctionAtAll12345"));
    }

