    /// Numbers at their edges, each as Excel's VBA answers.
    #[test]
    fn numbers_at_their_edges() {
        let value = run(
            "Public Function Ask() As String
               Ask = CDbl(\"(5)\") & \"|\" & CCur(0.00005) & \"|\" & CCur(0.00015) & \"|\" & CCur(\"0.00005\") & \"|\"
               Ask = Ask & TypeName(1.5 * CCur(3)) & TypeName(1.5 + CCur(3)) & TypeName(CCur(3) / CCur(2)) & \"|\"
               Ask = Ask & Fix(-0.5) & \"|\" & Val(\"&HFFFF\") & \"|\" & Val(\"&HFFFF&\") & \"|\"
               On Error Resume Next
               Dim d As Double
               d = 10 ^ 309
               Ask = Ask & Err.Number & \"|\"
               Err.Clear
               d = (-8) ^ (1 / 3)
               Ask = Ask & Err.Number
             End Function
",
            "Ask",
            vec![],
        )
        .unwrap();
        assert_eq!(value, Value::String("-5|0.0001|0.0001|0|DoubleCurrencyDouble|-0|-1|65535|6|5".to_string()));
    }

    /// Decimal as Excel's VBA has it: 28 places, exact sums, a Decimal from
    /// any arithmetic it takes part in, Long from Mod, Double from ^.
    #[test]
    fn decimal_is_its_own_type() {
        let value = run(
            "Public Function Ask() As String
               Ask = (CDec(1) / 3) & \"|\" & TypeName(CDec(1) + 1.5) & \"|\" & (CDec(0.1) + CDec(0.2) = 0.3) & \"|\"
               Ask = Ask & Round(CDec(\"2.345\"), 2) & \"|\" & TypeName(CDec(10) Mod 3) & TypeName(CDec(2) ^ 2) & \"|\" & VarType(CDec(1)) & \"|\"
               On Error Resume Next
               Ask = Ask & CDec(1E+30)
               Ask = Ask & Err.Number
             End Function
",
            "Ask",
            vec![],
        )
        .unwrap();
        assert_eq!(
            value,
            Value::String("0.3333333333333333333333333333|Decimal|True|2.34|LongDouble|14|6".to_string())
        );
    }

    /// An array is named for what it holds, and Join stops at a Null.
    /// Measured in Excel's VBA.
    #[test]
    fn arrays_are_named_for_what_they_hold() {
        let value = run(
            "Public Function Ask() As String
               Dim a() As Long, s(2) As String, v As Variant
               ReDim a(1)
               v = Split(\"a b\")
               Ask = TypeName(v) & VarType(a) & VarType(v) & VarType(s) & TypeName(Array(1)) & \"|\"
               On Error Resume Next
               Ask = Ask & Join(Array(1, Null), \"-\")
               Ask = Ask & Err.Number
             End Function
",
            "Ask",
            vec![],
        )
        .unwrap();
        assert_eq!(value, Value::String("String()819582008200Variant()|94".to_string()));
    }

    /// Err is the program's: what a function leaves in it reaches its caller
    /// unless the function left from its handler; On Error clears it; GoTo
    /// -1 clears it; a run-time error's Source is VBAProject. Measured.
    #[test]
    fn err_outlives_the_procedure_that_set_it() {
        let value = run(
            "Private Function Swallow() As Long
               On Error Resume Next
               Dim x As Long
               x = 1 / 0
             End Function
             Private Function Handled() As Long
               On Error GoTo H
               Dim x As Long
               x = 1 / 0
               Exit Function
             H:
             End Function
             Private Function Sees() As Long
               Sees = Err.Number
             End Function
             Public Function Ask() As String
               Dim o As String, x As Long
               On Error Resume Next
               x = Swallow()
               o = Err.Number & \"|\"
               x = Handled()
               o = o & Err.Number & \"|\"
               Err.Raise 7
               o = o & Sees() & \"|\"
               On Error GoTo -1
               o = o & Err.Number & \"|\"
               x = 1 / 0
               Ask = o & Err.Source
             End Function
",
            "Ask",
            vec![],
        )
        .unwrap();
        assert_eq!(value, Value::String("11|0|7|0|VBAProject".to_string()));
    }

    /// Named arguments to a Collection go to their places, and a Dictionary
    /// finds a number key whatever type it was given as. Measured in Excel.
    #[test]
    fn collection_named_arguments_and_numeric_dictionary_keys() {
        let value = run(
            "Public Function Ask() As String
               Dim c As New Collection, d As Object, v As Variant, s As String
               c.Add \"x\", \"kx\"
               c.Add \"y\", \"ky\"
               c.Add \"z\", Before:=1
               c.Add \"w\", After:=\"kx\"
               For Each v In c
                 s = s & v
               Next v
               Set d = CreateObject(\"Scripting.Dictionary\")
               d.Add 1, \"one\"
               d.Add \"1\", \"strone\"
               Ask = s & \"|\" & d.Count & d(1) & d(1#) & d(\"1\")
             End Function
",
            "Ask",
            vec![],
        )
        .unwrap();
        assert_eq!(value, Value::String("zxwy|2oneonestrone".to_string()));
    }

    /// Text through a picture of `@` and `&`, and text that is no number or
